<template><view class="portrait-panel" :class="['portrait-'+variant,{'portrait-ready':ready||artReady}]"><image v-if="ready||artReady" class="portrait-photo" :src="ready&&!preferIP?asset.src:art.src" mode="aspectFit" :aria-label="ready&&!preferIP?asset.caption:art.caption" @tap.stop="preview" @error="failed=true"/><template v-else><image class="portrait-landscape" src="/static/river.svg" mode="aspectFill"/><text class="portrait-era">人物文献 / ARCHIVE</text><text class="portrait-initial">{{name}}</text><text class="portrait-placeholder">史料照片待补 · 文献式题签</text></template><button v-if="ready&&artReady" class="portrait-mode" @tap.stop="preferIP=!preferIP">{{preferIP?'看史料照':'看IP形象'}}</button><text v-if="ready&&!preferIP&&asset.shortCaption" class="portrait-photo-caption">{{asset.shortCaption}}</text><button v-if="ready||artReady" class="portrait-credit" @tap.stop="source">{{ready&&!preferIP?(asset.creditLabel||'史料照片 · 图注来源 ↗'):'艺术化IP · 设计说明 ↗'}}</button></view></template>
<script setup>
import {computed,ref,watch} from 'vue';import portraits from '../data/人物肖像.json';
import artworks from '../data/IP形象.json';
const art=computed(()=>Object.values(artworks).find(a=>a.personId&&a.personId===props.personId)||{});const artReady=computed(()=>!failed.value&&Boolean(art.value.src));
const props=defineProps({personId:String,name:{type:String,default:'人物'},variant:{type:String,default:'card'}});const failed=ref(false);const preferIP=ref(false);const asset=computed(()=>portraits[props.personId]||{});const ready=computed(()=>!failed.value&&asset.value.identityVerified===true&&(asset.value.rightsApproved===true||asset.value.displayApproved===true)&&!!asset.value.src&&!!asset.value.sourceUrl&&!!asset.value.caption&&!!asset.value.rightsEvidence);watch(()=>props.personId,()=>{failed.value=false;preferIP.value=false});
function preview(){const src=ready.value&&!preferIP.value?asset.value.src:art.value.src;if(src)uni.previewImage({urls:[src],current:src})}
function source(){if(!ready.value||preferIP.value){uni.showModal({title:'艺术化IP形象',content:art.value.note+'\n素材记录：'+art.value.sourceFile,showCancel:false});return}const a=asset.value;uni.showModal({title:'人物图片资料',content:[a.caption,'时期：'+(a.period||'未确定'),a.sourceTitle,'使用依据：'+a.rightsEvidence].filter(Boolean).join('\n'),confirmText:'复制来源',success:r=>{if(r.confirm)uni.setClipboardData({data:a.sourceUrl})}})}
</script>
<style>
.portrait-panel{position:relative;overflow:hidden;background:#f1e7d5;width:100%;height:100%}.portrait-photo,.portrait-landscape{width:100%;height:100%;display:block}.portrait-landscape{opacity:.65}.portrait-initial{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:64px/1 STSong,SimSun,serif;color:#354d43}.portrait-placeholder{position:absolute;bottom:12px;left:16px;font-size:11px;letter-spacing:.06em;color:#75604b}.portrait-credit{position:absolute;bottom:8px;left:8px;min-height:36px;padding:6px 10px;background:#fffaf1e8;color:#982b28;font-size:12px;border-radius:8px}.portrait-cover{height:320px;max-width:280px;border:1px solid #ddd0b8;border-radius:12px;flex-shrink:0}.portrait-cover .portrait-initial{font-size:96px}@media(max-width:650px){.portrait-cover{height:210px;max-width:160px}.portrait-cover .portrait-initial{font-size:72px}}
</style>
<style>.portrait-initial{font-size:36px;letter-spacing:.1em;padding:16px;text-align:center}.portrait-cover .portrait-initial{font-size:46px}.portrait-placeholder{font-size:11px;line-height:1.7;right:10px}.portrait-landscape{opacity:.42}@media(max-width:650px){.portrait-cover .portrait-initial{font-size:38px}.portrait-initial{font-size:30px}.portrait-placeholder{left:12px;bottom:8px;font-size:10px}}</style>

<style>.portrait-mode{position:absolute;top:14px;right:14px;z-index:3;background:#fffaf1ed;border:1px solid #bd9a67;border-radius:18px;min-height:30px;padding:5px 10px;font-size:10px;line-height:1.4;display:flex;align-items:center;justify-content:center;color:#982b28;margin:0}.portrait-photo-caption{position:absolute;left:16px;right:16px;bottom:48px;font-size:10px;text-align:center;background:#fffaf1e8;color:#75604b;padding:4px 6px;border-radius:5px;z-index:2}</style>
